<?php
declare(strict_types=1);
namespace App\Interface\Http\QuestionLearning\Controller;
use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Application\QuestionLearning\DTO\Request\RequestQuestionExplanationRequestDto;use App\Application\QuestionLearning\Service\GetQuestionExplanationService;use App\Application\QuestionLearning\Service\RequestQuestionExplanationService;use App\Infrastructure\Http\ApiResponseFactory;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final readonly class QuestionExplanationController { public function __construct(private AuthService $auth,private RequestQuestionExplanationService $requests,private GetQuestionExplanationService $reads,private ApiResponseFactory $responses) {} public function request(ServerRequestInterface $r,ResponseInterface $p,AccessTokenRequestDto $access,RequestQuestionExplanationRequestDto $input):ResponseInterface { try{$user=$this->auth->currentUser($access);return $this->responses->success($p,$this->requests->execute($user->id,$input,new \DateTimeImmutable()),(string)$r->getAttribute('request_id'),202);}catch(\DomainException){return $this->responses->problem($p,'RESOURCE_NOT_FOUND','Recurso não encontrado.',404,(string)$r->getAttribute('request_id'));}}public function latest(ServerRequestInterface $r,ResponseInterface $p,AccessTokenRequestDto $access,string $questionId):ResponseInterface { try{$user=$this->auth->currentUser($access);$result=$this->reads->execute($user->id,$questionId);if($result===null)return $this->responses->problem($p,'RESOURCE_NOT_FOUND','Explicação não encontrada.',404,(string)$r->getAttribute('request_id'));return $this->responses->success($p,$result,(string)$r->getAttribute('request_id'));}catch(\DomainException){return $this->responses->problem($p,'UNAUTHENTICATED','Credenciais invalidas ou expiradas.',401,(string)$r->getAttribute('request_id'));}} }
